import numpy as np
import pandas as pd
from pandas._libs.tslibs import iNaT
from pandas._libs.tslibs import Timedelta
from pandas._libs.tslibs import Timestamp
from pandas.errors import OutOfBoundsDatetime

def record(name, ok, value=None, exc_type=None, exc_msg=None):
    probe(name, {
        'ok': ok,
        'value': repr(value) if ok else None,
        'exc_type': exc_type,
        'exc_msg': exc_msg,
    })

dti = pd.DatetimeIndex(np.array([iNaT + 1], dtype='M8[ns]'))
try:
    res = dti + Timedelta(-1, 'ns')
    record('expr_dti_plus_td_-1ns', True, res)
except Exception as e:
    record('expr_dti_plus_td_-1ns', False, exc_type=type(e).__name__, exc_msg=str(e))

dti_tz = pd.DatetimeIndex(np.array([iNaT + 1], dtype='M8[ns]'), tz='UTC')
try:
    res = dti_tz + Timedelta(-1, 'ns')
    record('expr_dti_tz_plus_td_-1ns', True, res)
except Exception as e:
    record('expr_dti_tz_plus_td_-1ns', False, exc_type=type(e).__name__, exc_msg=str(e))

tdi = pd.TimedeltaIndex(np.array([iNaT + 1], dtype='m8[ns]'))
try:
    res = tdi - Timedelta(1, 'ns')
    record('expr_tdi_minus_td_1ns', True, res)
except Exception as e:
    record('expr_tdi_minus_td_1ns', False, exc_type=type(e).__name__, exc_msg=str(e))

pi = pd.PeriodIndex([pd.Period(ordinal=iNaT + 1, freq='D')])
try:
    res = pi - 1
    record('expr_pi_minus_1', True, res)
except Exception as e:
    record('expr_pi_minus_1', False, exc_type=type(e).__name__, exc_msg=str(e))

# scalar
ts = pd.Timestamp(np.datetime64(iNaT + 1, 'ns'))
try:
    res = ts + Timedelta(-1, 'ns')
    record('expr_ts_plus_td_-1ns', True, res)
except Exception as e:
    record('expr_ts_plus_td_-1ns', False, exc_type=type(e).__name__, exc_msg=str(e))

try:
    res = ts + Timedelta(-2, 'ns')
    record('expr_ts_plus_td_-2ns', True, res)
except Exception as e:
    record('expr_ts_plus_td_-2ns', False, exc_type=type(e).__name__, exc_msg=str(e))

try:
    res = pd.Timestamp.min + pd.Timedelta(-1, 'ns')
    record('expr_ts_min_plus_td_-1ns', True, res)
except Exception as e:
    record('expr_ts_min_plus_td_-1ns', False, exc_type=type(e).__name__, exc_msg=str(e))

